/* PatentLens v38 — Five-stage research prototype. Frontend does not carry API keys. */
'use strict';
const $=id=>document.getElementById(id);
const norm=s=>String(s??'').normalize('NFC').replace(/\s+/g,' ').trim();
const fold=s=>norm(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/gi,'d').toLowerCase();
const esc=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const STAGES=[['intake','Nhập liệu','Tải PDF hoặc dán keyword, mô tả hay yêu cầu bảo hộ.'],['route','Định tuyến chủ đề','Nhận diện nhóm chính, concept và biến thể tìm kiếm từ kho thuật ngữ.'],['search','Tìm tài liệu theo nhóm','Chạy các truy vấn, xem nguồn và lựa chọn D1–D3.'],['compare','So sánh bằng chứng','Đối chiếu từng claim-feature hoặc từng concept với từng tài liệu.'],['report','Nhận định và báo cáo','Tổng hợp mức độ bằng chứng; chuyên gia rà soát lần cuối.']];
const S={stage:0,mode:'prospective',source:'',filename:'',fileMeta:null,pdf:null,pages:[],unread:[],pdfBusy:false,pdfAbort:false,uploadId:0,ocrToken:0,claims:[],keywordOnly:true,route:null,routeAudit:null,concepts:[],claimDates:{},queries:[],queryLog:[],candidates:[],prior:{D1:null,D2:null,D3:null},features:[],matrix:{},ai:{},aiCoverage:{},searching:false,searchAbort:null,aiBusy:false,aiStop:false,expertNote:'',signed:false,reportHtml:'',revision:0};
function notify(message,error=false){const el=$('alert');el.textContent=message;el.className='alert '+(error?'error':'success');el.hidden=false;}
function clearNotice(){$('alert').hidden=true;}
function safeUrl(url){try{const u=new URL(url);return u.protocol==='https:'?u.href:'';}catch{return '';}}
function titleText(){return norm(S.source.split(/[\n.!?]/)[0]).slice(0,200);}
function stepShow(n){S.stage=Math.max(0,Math.min(STAGES.length-1,n));clearNotice();document.querySelectorAll('.stage').forEach((p,i)=>p.classList.toggle('active',i===S.stage));const st=STAGES[S.stage];$('stepCount').textContent=`BƯỚC ${String(S.stage+1).padStart(2,'0')} / 05`;$('stepTitle').textContent=st[1];$('stepIntro').textContent=st[2];$('wizardInfo').textContent=`Bước ${S.stage+1}/5`;$('back').disabled=S.stage===0;$('next').textContent=S.stage===4?'Tạo báo cáo':'Tiếp tục →';$('steps').innerHTML=STAGES.map((s,i)=>`<button type="button" class="stepbtn ${i===S.stage?'active':''}" data-step="${i}" ${i>S.stage?'disabled title="Đi theo luồng từ bước trước"':''}><i>${i+1}</i><span>${esc(s[1])}</span></button>`).join('');$('steps').querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{if(+b.dataset.step<=S.stage)stepShow(+b.dataset.step);});if(S.stage===1)renderRoute();if(S.stage===2)renderSearchStage();if(S.stage===3)renderMatrix();if(S.stage===4)renderReport();window.scrollTo({top:0,behavior:'instant'});}
function invalidate(from){S.revision++;if(from<=1){S.route=null;S.concepts=[];S.queries=[];}if(from<=2){S.queryLog=[];S.candidates=[];S.prior={D1:null,D2:null,D3:null};}if(from<=3){S.features=[];S.matrix={};S.ai={};S.aiCoverage={};S.claimDates={};if($('claimInputVerified'))$('claimInputVerified').checked=false;}S.reportHtml='';}
function setInput(text,filename=''){const t=String(text||'').normalize('NFC');if(!t.trim())return notify('Chưa có nội dung để phân tích.',true);invalidate(1);S.source=t;S.filename=filename;S.claims=parseStructuredClaims(t);S.keywordOnly=!S.claims.length;const mode=S.keywordOnly?'keyword-only: không phát hiện claims có cấu trúc':'claim-based: đã nhận diện '+S.claims.length+' claims';$('ingestState').textContent=`Đã nạp ${t.length.toLocaleString('vi-VN')} ký tự · ${mode}.`;$('claimsPreview').innerHTML=S.claims.length?S.claims.map(c=>`<article><strong>Claim ${c.id}${c.dependsOn.length?' · phụ thuộc '+c.dependsOn.join(', '):''}${c.dependencyIssue?' · phụ thuộc nhiều nhánh/chưa rõ; chờ chuyên gia':''}</strong><p>${esc(c.text)}</p></article>`).join(''):'<p>Không có bộ claims được xác nhận từ cấu trúc. Máy giữ nguyên keyword/mô tả để tra cứu; không bịa claim.</p>';}
function parseStructuredClaims(full){
  const lines=String(full||'').replace(/\r/g,'').split('\n');
  const heading=/^\s*(?:y[eê]u\s*c[aầ]u\s*b[aả]o\s*h[ộo]|claims?\b|what\s+is\s+claimed|ph[aầ]n\s+y[eê]u\s*c[aầ]u\s*b[aả]o\s*h[ộo])\s*[:：.\-]?\s*$/iu;
  let start=lines.findIndex(l=>heading.test(l));
  const marker=/^\s*(\d{1,3})\s*[.)](?!\d)\s+(?=\S)/u;
  const form=/^(?:m[ộo]t\s+|a\s+|an\s+|the\s+|ph[ưươ]ơng\s+ph[aá]p\b|quy\s+tr[ìi]nh\b|thi[eế]t\s+b[ịi]\b|h[ệe]\s+th[ốo]ng\b)/iu;
  // A numbered description is not enough: explicit CLAIMS heading, or at least
  // two sequential, claim-like lines supplied as text are required.
  if(start<0){const cand=lines.map((l,i)=>({i,m:l.match(marker)})).filter(x=>x.m&&form.test(lines[x.i].slice(x.m[0].length)));if(cand.length<2||cand[0].m[1]!=='1'||Number(cand[1].m[1])!==2)return [];start=cand[0].i-1;}
  const out=[];let current=null;
  const endHeading=/^\s*(?:description|detailed\s+description|abstract|summary|m[ôo]\s+t[aả]\s+chi\s+ti[eế]t|h[ìi]nh\s+v[ẽe]|drawings?|technical\s+field|l[ĩi]nh\s+v[ựu]c\s+k[ỹy]\s+thu[ậa]t)\s*[:：]?\s*$/iu;
  const finish=()=>{if(current){current.text=norm(current.buffer.join(' ')).replace(new RegExp('^'+current.id+'\\s*[.)]\\s*'),'');delete current.buffer;if(current.text.length>=15)out.push(current);current=null;}};
  for(let i=start+1;i<lines.length;i++){
    const line=lines[i].trim();if(!line)continue;
    if(endHeading.test(line)&&out.length){finish();break;}
    const m=line.match(marker);const next=current?current.id+1:out.length+1;
    if(m&&Number(m[1])===next){
      // Avoid a decimal or list item misread as a claim; require meaningful content.
      if(current)finish();current={id:Number(m[1]),buffer:[line.slice(m[0].length)]};continue;
    }
    if(current)current.buffer.push(line);
  }
  finish();
  if(!out.length||out[0].id!==1)return [];
  return out.map(c=>{const multi=/(?:claims?|yêu\s+cầu\s+bảo\s+hộ|điểm)\s*\d{1,3}\s*(?:[-–]|to|đến|or|hoặc|and|và)\s*\d{1,3}/iu.test(c.text);const m=c.text.match(/(?:the\s+\w+\s+of\s+claim|the\s+\w+\s+according\s+to\s+claim|(?:theo|của)\s+(?:yêu\s+cầu\s+bảo\s+hộ|điểm|claim))\s*(\d{1,3})/iu);const parent=m?Number(m[1]):0;return {...c,dependsOn:!multi&&parent>0&&parent<c.id?[parent]:[],dependencyIssue:multi||parent>=c.id};});
}
function inputDataRequired(){if(S.pdfBusy){notify('PDF đang đọc lớp chữ. Có thể dừng và thử lại nếu cần.',true);return false;}if(!S.source.trim()){notify('Hãy tải PDF hoặc dán nội dung và bấm “Sử dụng văn bản”.',true);return false;}return true;}
function routeAllText(){const api=window.PATENTLENS_TOPIC_ROUTER;if(!api)throw Error('Chưa tải được kho thuật ngữ topic_lexicon.js.');const text=S.source;const chunks=[];for(let p=0;p<text.length;p+=180000)chunks.push(text.slice(p,p+180000));const byTopic=new Map();let chars=0;for(const chunk of chunks.length?chunks:['']){const scan=api.scan(chunk,{maxChars:200000});chars+=scan.scannedChars;for(const topic of scan.topics){let t=byTopic.get(topic.id);if(!t){t={id:topic.id,name:topic.name,matchedConcepts:[],conceptCount:0};byTopic.set(t.id,t);}for(const c of topic.matchedConcepts){let old=t.matchedConcepts.find(v=>v.id===c.id);if(!old){old={...c,matched:[],alternatives:[...c.alternatives]};t.matchedConcepts.push(old);}for(const m of c.matched)if(!old.matched.includes(m))old.matched.push(m);}}}const topics=[...byTopic.values()].map(t=>({...t,conceptCount:t.matchedConcepts.length})).sort((a,b)=>b.conceptCount-a.conceptCount);S.route={topics,scannedChars:chars,totalChars:text.length,complete:chars===text.length};S.routeAudit={scannedChars:chars,totalChars:text.length};S.concepts=topics.flatMap(t=>t.matchedConcepts.map(c=>({id:t.id+'::'+c.id,topic:t.name,name:c.name,source:c.matched,alternatives:c.alternatives})));if(!S.concepts.length&&S.keywordOnly&&text.length<=160){S.concepts=[{id:'unclassified::raw',topic:'Chưa xác định',name:norm(text),source:[norm(text)],alternatives:[]}];}}
function renderRoute(){if(!S.route)routeAllText();$('modeBadge').textContent=S.keywordOnly?'Chế độ keyword-only · chưa có claims':'Chế độ claims · '+S.claims.length+' claims có cấu trúc';$('originalPreview').value=S.source.length>20000?S.source.slice(0,20000):S.source;$('routeScope').textContent=`Đã rà thuật ngữ trên ${S.route.scannedChars.toLocaleString('vi-VN')} / ${S.route.totalChars.toLocaleString('vi-VN')} ký tự đã nạp. Ô xem trước chỉ hiển thị tối đa 20.000 ký tự.`;
 $('routeResult').innerHTML=S.route.topics.length?S.route.topics.map(t=>`<div class="topic-card"><h3>${esc(t.name)} <span class="tag">${t.conceptCount} concept</span></h3>${t.matchedConcepts.map(c=>`<div class="topic-concept"><strong>${esc(c.name)}</strong><br><small>Thuật ngữ gốc khớp: ${esc(c.matched.join(' · '))}</small><br><small>Biến thể tìm kiếm (cần kiểm tra): ${esc(c.alternatives.join(' · ')||'—')}</small></div>`).join('')}</div>`).join(''):'<div class="notice">Kho thuật ngữ hiện chưa khớp. Bạn vẫn có thể dùng keyword gốc để tìm; không được tự thêm synonym hoặc ép hồ sơ vào một nhóm.</div>';
}
function searchTerms(){const seen=new Set(),out=[];const add=(query,label,concept)=>{const q=norm(query).replace(/[<>`]/g,'').slice(0,110);if(q.length<3)return;const k=fold(q);if(seen.has(k))return;seen.add(k);out.push({q,label,concept});};for(const c of S.concepts.slice(0,7)){const source=c.source.find(x=>x.length>=5)||c.source[0];if(source)add(source,c.topic+' · '+c.name,c.id);const english=c.alternatives.find(x=>/^[a-z][a-z -]{4,}$/i.test(x));if(english)add(english,c.topic+' · '+c.name+' (EN)',c.id);}if(!out.length){const lines=S.source.split(/[\n,;]+/).map(norm).filter(x=>x.length>=4&&x.length<=110);lines.slice(0,6).forEach(t=>add(t,'Từ khóa gốc','raw'));if(!out.length&&S.source.length<180)add(S.source,'Từ khóa gốc','raw');}return out.slice(0,7);}
function renderSearchStage(){if(!S.queries.length)S.queries=searchTerms();if(!$('searchQueries').value.trim())$('searchQueries').value=S.queries.map(x=>x.q).join('\n');renderSourceLinks();renderCandidates();renderPrior();renderSearchLog();}
function renderSourceLinks(){let queries=$('searchQueries').value.split('\n').map(norm).filter(Boolean);const q=(queries[0]||S.queries[0]?.q||'patent').slice(0,160);const list=[['Google Patents','https://patents.google.com/?q='+encodeURIComponent(q)],['WIPO · thủ công','https://patentscope.wipo.int/search/en/advancedSearch.jsf?query='+encodeURIComponent('EN_ALLTXT:('+q+')')],['Espacenet · thủ công','https://worldwide.espacenet.com/patent/search?q='+encodeURIComponent(q)],['Cục SHTT VN · thủ công','https://ipvietnam.gov.vn/']];$('sourceLinks').innerHTML=list.map(([n,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(n)} ↗</a>`).join('');}
function renderSearchLog(){const lines=S.queryLog.map(r=>`[${r.status}] ${r.provider||'Không rõ nguồn'} · ${r.query} · ${r.count??0} kết quả${r.error?' · '+r.error:''}`);$('searchLog').textContent=lines.join('\n')||'Chưa có lượt tìm.';}
function ranking(candidate,queries){const text=fold(candidate.title+' '+candidate.snippet);let hits=0;for(const q of queries){const words=fold(q).replace(/[^a-z0-9\s]/g,' ').split(/\s+/).filter(w=>w.length>3);if(words.length&&words.some(w=>text.includes(w)))hits++;}return hits;}
async function runSearch(){if(!$('searchConsent').checked)return notify('Hãy xác nhận quyền gửi truy vấn kỹ thuật trước khi gọi dịch vụ tìm kiếm.',true);const queries=$('searchQueries').value.split('\n').map(norm).filter(Boolean).slice(0,8);if(!queries.length)return notify('Chưa có truy vấn hợp lệ.',true);S.searching=true;S.searchAbort=new AbortController();$('runSearch').disabled=true;$('stopSearch').hidden=false;S.queryLog=[];S.candidates=[];renderCandidates();renderSearchLog();const byNo=new Map();for(let i=0;i<queries.length;i++){
 if(S.searchAbort.signal.aborted)break;const q=queries[i].slice(0,160);$('searchProgress').textContent=`Đang chạy ${i+1}/${queries.length}: ${q}`;
 try{const url='/api/search?q='+encodeURIComponent(q)+'&num=12&mode=precise';const response=await fetch(url,{cache:'no-store',signal:AbortSignal.any([S.searchAbort.signal,AbortSignal.timeout(45000)]),headers:$('apiCode').value.trim()?{'x-public-api-access-code':$('apiCode').value.trim()}: {}});const result=await response.json();for(const l of result.search_log||[])S.queryLog.push({...l});if(!response.ok||!result.ok){if(!result.search_log?.length)S.queryLog.push({status:result.code||'ERROR',query:q,provider:'Backend',error:result.error||`HTTP ${response.status}`,count:0});continue;}for(const c of result.results||[]){const no=String(c.publication_number||'').replace(/[^A-Za-z0-9]/g,'').toUpperCase();if(!no)continue;if(S.filename&&norm(S.filename).toUpperCase().includes(no))continue;const known=byNo.get(no);if(known){known.foundQueries.add(q);continue;}byNo.set(no,{...c,publication_number:no,foundQueries:new Set([q]),sources:new Set([c.discovery_provider||result.provider||'không rõ'])});}if(!result.search_log?.length)S.queryLog.push({query:q,provider:result.provider,status:(result.results||[]).length?'OK':'ZERO',count:(result.results||[]).length});}
 catch(e){if(S.searchAbort.signal.aborted)break;S.queryLog.push({query:q,provider:'Kết nối',status:'ERROR',error:String(e.message||e).slice(0,180),count:0});}
 S.candidates=[...byNo.values()].map(c=>({...c,foundQueries:[...c.foundQueries],sources:[...c.sources],relevance:ranking(c,queries)})).sort((a,b)=>b.relevance-a.relevance||b.foundQueries.length-a.foundQueries.length);renderCandidates();renderSearchLog();await new Promise(r=>setTimeout(r,0));}
 S.searching=false;$('runSearch').disabled=false;$('stopSearch').hidden=true;const failures=S.queryLog.filter(x=>x.status==='ERROR').length;$('searchProgress').textContent=`Đã chạy ${S.queryLog.length} lượt có log · ${S.candidates.length} mã công bố khác nhau · ${failures} lượt lỗi. ${failures?'Cần kiểm tra nguồn chưa chạy thành công.':'Không bảo đảm tra cứu đầy đủ.'}`;}
function renderCandidates(){const root=$('candidates');root.innerHTML=S.candidates.length?S.candidates.slice(0,80).map((c,i)=>`<article class="candidate"><div class="candidate-head"><h3>${i+1}. ${esc(c.title||c.publication_number)}</h3><span class="tag">Ưu tiên đọc: ${c.relevance?'có thuật ngữ khớp':'cần xem thêm'}</span></div><p><strong>${esc(c.publication_number)}</strong> · Công bố: ${esc(c.publication_date||'chưa rõ')} · Nguồn tìm: ${esc(c.sources?.join(', ')||c.discovery_provider||'chưa rõ')}</p><p class="muted small">${esc((c.snippet||'Không có snippet.').slice(0,420))}</p><p class="muted small">Chỉ dựa metadata/snippet · chưa kiểm tra toàn văn, hình vẽ hoặc tư cách đối chứng.</p><div class="inline"><a target="_blank" rel="noopener noreferrer" href="${esc(safeUrl(c.url)||'https://patents.google.com/patent/'+encodeURIComponent(c.publication_number)+'/en')}">Mở nguồn ↗</a>${['D1','D2','D3'].map(s=>`<button class="btn" data-pick="${i}" data-slot="${s}">Chọn ${s}</button>`).join('')}</div></article>`).join(''):'<p class="muted">Chưa có ứng viên. Nếu nguồn lỗi hoặc chưa cấu hình, dùng liên kết tra thủ công và nhập tài liệu công khai vào D1–D3.</p>';root.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>selectPrior(b.dataset.slot,S.candidates[+b.dataset.pick]));}
function selectPrior(slot,c){if(!c)return;S.prior[slot]={no:c.publication_number,title:c.title||'',date:c.publication_date||'',url:c.url||'',text:c.snippet||'',content_level:c.snippet?'snippet_only':'metadata_only',sourceChecked:false,dateChecked:false,docIdentityChecked:false,combinationClaims:{},loadedFrom:'search'};clearSlot(slot);renderPrior();notify(`${slot} đã chọn. Hãy mở bản gốc/đọc thêm toàn văn rồi kiểm tra từng đoạn tại Bước 4.`);}
function clearSlot(slot){for(const key of Object.keys(S.matrix))if(key.endsWith('::'+slot))delete S.matrix[key];for(const key of Object.keys(S.ai))if(key.endsWith('::'+slot))delete S.ai[key];delete S.aiCoverage[slot];S.reportHtml='';}
function renderPrior(){const root=$('priorSlots');root.innerHTML=['D1','D2','D3'].map(slot=>{const d=S.prior[slot]||{};return `<article class="prior-slot" data-prior="${slot}"><div class="slot-head"><h3>${slot} · ${esc(d.no||'Chưa chọn')}</h3>${d.url?`<a target="_blank" rel="noopener noreferrer" href="${esc(safeUrl(d.url))}">Mở nguồn gốc ↗</a>`:''}</div><label>Mã công bố<input data-field="no" value="${esc(d.no||'')}" placeholder="Ví dụ: US2020123456A1"></label><label>Ngày công bố theo nguồn (chưa xác minh)<input data-field="date" type="date" value="${/^\d{4}-\d{2}-\d{2}$/.test(d.date||'')?d.date:''}"></label><label>Link tài liệu gốc<input data-field="url" value="${esc(d.url||'')}" placeholder="https://..."></label><label>Văn bản đang dùng để tìm chứng cứ <span class="tag ${d.content_level==='snippet_only'?'yellow':''}">${esc(d.content_level||'Chưa nạp')}</span><textarea rows="5" data-field="text" placeholder="Đọc bản gốc hoặc dán nguyên văn những phần được phép sử dụng">${esc(d.text||'')}</textarea></label><div class="inline"><button class="btn" data-detail="${slot}">Thử đọc thêm tài liệu gốc</button><button class="btn" data-remove="${slot}">Bỏ ${slot}</button></div><label class="check"><input type="checkbox" data-verify="sourceChecked" ${d.sourceChecked?'checked':''}> Tôi đã mở và đối chiếu các đoạn nguồn với đúng bản tài liệu công khai.</label><label class="check"><input type="checkbox" data-verify="docIdentityChecked" ${d.docIdentityChecked?'checked':''}> Tôi đã kiểm tra mã công bố/phiên bản nguồn.</label><label class="check"><input type="checkbox" data-verify="dateChecked" ${d.dateChecked?'checked':''}> Tôi đã kiểm tra ngày công bố và tư cách đối chứng cho trường hợp đang xét.</label><p class="muted small">Không được coi snippet/tóm tắt là đã đọc toàn văn; ngày ưu tiên của từng claim cần kiểm tra riêng.</p></article>`}).join('');root.querySelectorAll('[data-prior]').forEach(el=>{const slot=el.dataset.prior;el.querySelectorAll('[data-field]').forEach(input=>input.onchange=()=>{if(!S.prior[slot])S.prior[slot]={combinationClaims:{},loadedFrom:'manual'};const d=S.prior[slot],k=input.dataset.field;d[k]=input.value;if(k==='text'){d.content_level='user_supplied';d.sourceChecked=false;}else if(k==='no'||k==='url'){d.sourceChecked=false;d.docIdentityChecked=false;}else if(k==='date')d.dateChecked=false;clearSlot(slot);renderPrior();});el.querySelectorAll('[data-verify]').forEach(input=>input.onchange=()=>{if(!S.prior[slot])return;S.prior[slot][input.dataset.verify]=input.checked;S.reportHtml='';});el.querySelector('[data-detail]').onclick=()=>loadDetail(slot);el.querySelector('[data-remove]').onclick=()=>{S.prior[slot]=null;clearSlot(slot);renderPrior();};});}
async function loadDetail(slot){const d=S.prior[slot];if(!d?.no)return notify(`Hãy nhập mã công bố cho ${slot} trước.`,true);const btn=document.querySelector(`[data-detail="${slot}"]`);btn.disabled=true;try{const r=await fetch('/api/detail?pub='+encodeURIComponent(d.no),{signal:AbortSignal.timeout(30000),headers:$('apiCode').value.trim()?{'x-public-api-access-code':$('apiCode').value.trim()}: {}});const x=await r.json();if(!r.ok||!x.ok)throw Error(x.error||`HTTP ${r.status}`);const pieces=[x.claims&&'CLAIMS\n'+x.claims,x.description&&'DESCRIPTION\n'+x.description].filter(Boolean);d.text=pieces.length?pieces.join('\n\n'):x.abstract||d.text;d.content_level=x.content_level||'metadata_only';d.url=x.url||d.url;d.sourceChecked=false;d.docIdentityChecked=false;clearSlot(slot);renderPrior();notify(`${slot}: đã tải ${d.content_level}. Chưa xác thực toàn văn, hình vẽ, ngữ cảnh và bản gốc.`);}catch(e){notify(`Không tải được ${slot}: ${String(e.message||e)}. Bạn vẫn có thể mở nguồn gốc và bổ sung văn bản thủ công.`,true);}finally{if(btn?.isConnected)btn.disabled=false;}}
function featuresFromClaims(){if(S.keywordOnly)return S.concepts.map(c=>({id:'T-'+c.id,text:c.name,claimId:0,kind:'concept',source:c.source,topic:c.topic}));const byId=new Map(S.claims.map(c=>[c.id,c]));const own=new Map();for(const c of S.claims){const parts=c.text.split(/\s*;\s*|\s+(?=(?:trong\s+đó|wherein|whereby)\b)/iu).map(norm).filter(Boolean);const chosen=parts.length>1?parts:[c.text];own.set(c.id,chosen.map((text,i)=>({id:`C${c.id}-F${String(i+1).padStart(2,'0')}`,text,claimId:c.id,kind:'feature',inheritedFrom:null})));}let features=[];for(const c of S.claims){const visited=new Set([c.id]);const chain=[];let parent=c.dependsOn[0];while(parent&&byId.has(parent)&&!visited.has(parent)){visited.add(parent);chain.unshift(parent);parent=byId.get(parent).dependsOn[0];}for(const id of chain){for(const f of own.get(id)||[])features.push({...f,id:`C${c.id}←${f.id}`,claimId:c.id,inheritedFrom:id});}features.push(...own.get(c.id));}return features;}
function matrixKey(id,slot){return id+'::'+slot;}
function matrixRowStatus(id,slot){return S.matrix[matrixKey(id,slot)]?.status||'Chưa có dữ liệu';}
function quotedInDocument(quote,doc){const q=norm(quote).toLocaleLowerCase(),t=norm(doc||'').toLocaleLowerCase();return q.length>=16&&t.includes(q);}
function lexicalHint(feature,d){if(!d?.text||d.text.length<35)return '';const terms=feature.kind==='concept'?(feature.source||[]):[...new Set(feature.text.match(/[\p{L}]{5,}/gu)||[])].slice(0,10);const body=fold(d.text);for(const term of terms){const needle=fold(term);if(needle.length<5)continue;const index=body.indexOf(needle);if(index>=0){const snippet=d.text.slice(Math.max(0,index-65),Math.min(d.text.length,index+needle.length+180));return snippet;}}return '';}
function renderMatrix(){if(!S.features.length)S.features=featuresFromClaims();$('compareMode').textContent=S.keywordOnly?'Keyword-only: so sánh từng concept. Không có yêu cầu bảo hộ nên KHÔNG đánh giá tính mới/trình độ sáng tạo.':'Có claims: ma trận theo từng feature của từng claim, bao gồm giới hạn kế thừa khi xác định được claim cha. Máy không tự phê duyệt bằng chứng.';const root=$('matrix');if(!S.features.length){root.innerHTML='<p>Chưa có concept nào nhận diện. Hãy bổ sung keyword hoặc dữ liệu nguồn trước khi đối chiếu.</p>';return;}root.innerHTML=S.features.map((f,i)=>`<article class="matrix-row" data-feature="${i}"><header><div><span class="tag">${esc(f.id)}</span> ${f.inheritedFrom?`<span class="tag yellow">Kế thừa claim ${f.inheritedFrom}</span>`:''}<p>${esc(f.text)}</p></div></header><div class="matrix-cols">${['D1','D2','D3'].map(slot=>{const d=S.prior[slot],key=matrixKey(f.id,slot),r=S.matrix[key]||{},a=S.ai[key],hint=lexicalHint(f,d);return `<div class="cell" data-cell="${esc(key)}" data-slot="${slot}"><strong>${slot}</strong> <span class="tag ${r.status==='Có'?'green':r.status==='Chưa chắc chắn'?'yellow':''}">${esc(matrixRowStatus(f.id,slot))}</span><p class="muted small">${esc(d?.no||'Chưa nạp tài liệu')}</p>${a?`<div class="notice cell-note">AI gợi ý: ${esc(a.status)} · ${esc(a.evidence||'chưa có câu trích')} <br>Chỉ khớp trong văn bản đã gửi, chưa xác minh nguồn.</div>`:hint?`<p class="muted small">Gợi ý trùng thuật ngữ trong văn bản đã nạp: “${esc(hint)}” (chưa phải bằng chứng kỹ thuật).</p>`:''}<details><summary>Chuyên gia kiểm tra ô này</summary><label>Trạng thái<select data-review="status"><option>Chưa có dữ liệu</option><option>Chưa chắc chắn</option><option>Có</option><option>Một phần</option></select></label><label>Đoạn trích nguyên văn<textarea rows="3" data-review="quote" placeholder="Dán đúng câu từ bản tài liệu đang dùng"></textarea></label><label>Vị trí trong bản gốc<input data-review="location" placeholder="Claim 2 / [0024] / tr.3 / Fig.1"></label><label>Nhận xét chuyên gia<input data-review="note" placeholder="Nêu căn cứ phù hợp/khác biệt, giới hạn kỹ thuật"></label><button class="btn" data-save-cell="${i}" ${d?.no?'':'disabled'}>Lưu xác nhận của chuyên gia</button><p class="cell-note muted" data-review-message>${r.checked?'Đã lưu; nguồn và trích dẫn vẫn cần kiểm tra ngữ nghĩa.':'Chưa có quyết định đã lưu.'}</p></details></div>`}).join('')}</div></article>`).join('');root.querySelectorAll('[data-cell]').forEach(cell=>{const key=cell.dataset.cell,r=S.matrix[key]||{};for(const field of ['status','quote','location','note']){const el=cell.querySelector(`[data-review="${field}"]`);el.value=r[field]|| (field==='status'?'Chưa có dữ liệu':'');}cell.querySelector('[data-save-cell]').onclick=()=>saveCell(cell);});}
function saveCell(cell){const key=cell.dataset.cell,slot=cell.dataset.slot,d=S.prior[slot],status=cell.querySelector('[data-review="status"]').value,quote=norm(cell.querySelector('[data-review="quote"]').value),location=norm(cell.querySelector('[data-review="location"]').value),note=norm(cell.querySelector('[data-review="note"]').value);const feedback=cell.querySelector('[data-review-message]');if(!d?.no){feedback.textContent='Chưa có tài liệu '+slot;return;}if(['Có','Một phần'].includes(status)&&(!d.sourceChecked||!d.docIdentityChecked||!location||note.length<8||!quotedInDocument(quote,d.text))){feedback.textContent='Chưa lưu: phải kiểm tra đúng mã/bản gốc, nhập đoạn trích khớp chữ trong văn bản đã nạp (≥16 ký tự), vị trí và nhận xét ít nhất 8 ký tự.';return;}S.matrix[key]={status,quote,location,note,checked:true,at:new Date().toISOString(),sourceNo:d.no,sourceUrl:d.url||'',sourceRevision:S.revision};S.reportHtml='';feedback.textContent='Đã lưu quyết định của chuyên gia; không phải chứng thực pháp lý tự động.';cell.querySelector('.tag').textContent=status;}
function textChunks(text,max=5800,overlap=300){const t=String(text||''),out=[];let start=0;while(start<t.length){const end=Math.min(start+max,t.length);out.push({start,end,text:t.slice(start,end)});if(end===t.length)break;start=Math.max(start+1,end-Math.min(overlap,Math.floor(max/3)));}let covered=0;for(const c of out){if(c.start>covered)throw Error('CHUNK_GAP: đoạn đầu vào bị bỏ sót');covered=Math.max(covered,c.end);}if(covered!==t.length)throw Error('CHUNK_GAP: không bao phủ cuối văn bản');return out;}
function chunkFingerprint(text){const x=String(text||'');let h=2166136261;for(let i=0;i<x.length;i++)h=Math.imul(h^x.charCodeAt(i),16777619);return x.length+':'+(h>>>0).toString(16);}
async function runAi(){if(S.keywordOnly)return notify('Chế độ keyword-only dùng bảng concept và chuyên gia đối chiếu. Chưa gửi concept như thể đó là feature của claim.',true);if($('privateMode').checked||!$('aiConsent').checked)return notify('Chỉ chạy Gemini khi tài liệu được phép gửi ra ngoài: bỏ chế độ bảo mật và tích đồng ý tại phần Quyền gửi dữ liệu.',true);const pwd=$('deepCode').value.trim();if(pwd.length<12)return notify('Hãy nhập mã truy cập AI chuyên sâu đã đặt trong Cloudflare; không nhập khóa Gemini thật vào website.',true);if(!S.features.length)S.features=featuresFromClaims();const docs=['D1','D2','D3'].filter(slot=>S.prior[slot]?.text?.length>40 && !['snippet_only','metadata_only','abstract_only'].includes(S.prior[slot].content_level));if(!docs.length)return notify('Chưa có D1–D3 có nội dung claims/mô tả đủ để tìm trích dẫn. Snippet không được dùng làm toàn văn.',true);if(S.aiBusy)return;S.aiBusy=true;S.aiStop=false;$('aiAssist').disabled=true;$('aiProgress').textContent='Đang kiểm toán độ phủ văn bản...';let done=0,failed=0,total=0;const slots=[];try{for(const slot of docs){const chunks=textChunks(S.prior[slot].text);slots.push({slot,chunks,features:S.features.filter(f=>f.text.length<=2000)});total+=chunks.length*Math.ceil(S.features.filter(f=>f.text.length<=2000).length/3);}if(total>240){S.aiCoverage={};return notify(`Có ${total} lượt Gemini cần chạy. Để tránh vô tình phát sinh chi phí lớn, hãy chia hồ sơ thành các đợt được chuyên gia cho phép. Không đánh dấu các phần chưa chạy là đã được đọc.`,true);}for(const item of slots){const {slot,chunks,features}=item,doc=S.prior[slot],pending=new Set();for(let k=0;k<chunks.length;k++)for(let p=0;p<features.length;p+=3){if(S.aiStop){failed++;break;}const c=chunks[k],batch=features.slice(p,p+3);$('aiProgress').textContent=`${slot}: đoạn ${k+1}/${chunks.length} · ${done+failed+1}/${total} lượt`;try{const res=await fetch('/api/matrix',{method:'POST',signal:AbortSignal.timeout(68000),headers:{'content-type':'application/json','x-deep-access-code':pwd,...($('apiCode').value.trim()?{'x-public-api-access-code':$('apiCode').value.trim()}:{})},body:JSON.stringify({features:batch.map(f=>({id:f.id,text:f.text})),documents:{[slot]:{no:doc.no,text:c.text}},external_ai_consent:true,confidential_mode:false})});const j=await res.json();if(!res.ok||!j.ok)throw Error(j.error||'Lượt Gemini lỗi');if(j.scan_echo?.chunk_fingerprint!==chunkFingerprint(c.text)||j.scan_echo?.received_chars!==c.text.length)throw Error('Worker nhận khác đoạn đã gửi, không đánh dấu hoàn tất');for(const f of batch){const row=j.rows?.find(r=>r.feature_id===f.id),suggest=row?.[slot];if(!suggest)throw Error('MODEL_INCOMPLETE');const evidence=norm(suggest.evidence||'');if(!['Có','Một phần'].includes(suggest.status)||!evidence)continue;const key=matrixKey(f.id,slot);if(S.ai[key]&&S.ai[key].evidence.length>=evidence.length)continue;S.ai[key]={status:suggest.status,evidence,literalTextMatch:!!suggest.literal_text_match,sourceVerified:false};}done++;}catch(e){failed++;pending.add(`${k+1}: ${String(e.message||e).slice(0,110)}`);}}S.aiCoverage[slot]={done,failed,planned:chunks.length*Math.ceil(features.length/3),complete:!S.aiStop&&!pending.size,issues:[...pending],textChars:doc.text.length};if(S.aiStop)break;}$('aiProgress').textContent=`AI hoàn tất ${done}/${total} lượt, lỗi/chưa chạy ${failed}. Gợi ý vẫn cần chuyên gia đối chiếu với bản gốc. ${failed?'Không được coi phần chưa chạy là vắng mặt.':''}`;renderMatrix();}catch(e){notify('Không thực hiện được đối chiếu AI: '+String(e.message||e),true);}finally{S.aiBusy=false;$('aiAssist').disabled=false;}}
function cellSummary(){const counts={checked:0,proposed:Object.keys(S.ai).length,total:S.features.length*3};for(const x of Object.values(S.matrix))if(x.checked)counts.checked++;return counts;}
function claimFeatureGroup(){const m=new Map();for(const f of S.features){const k=f.claimId||0;let a=m.get(k);if(!a){a=[];m.set(k,a);}a.push(f);}return m;}
function assessClaim(claim){const group=claimFeatureGroup().get(claim.id)||[],slotResults=[];for(const slot of ['D1','D2','D3']){const d=S.prior[slot];if(!d?.no)continue;const statuses=group.map(f=>S.matrix[matrixKey(f.id,slot)]);const complete=statuses.length===group.length&&statuses.every(r=>r?.checked&&r.status==='Có'&&r.sourceNo===d.no);const dateKnown=!!(d.date&&d.dateChecked);const sameCombination=!!d.combinationClaims?.[claim.id];if(complete)slotResults.push({slot,no:d.no,dateKnown,sourceChecked:!!(d.sourceChecked&&d.docIdentityChecked),sameCombination});}const meta=S.claimDates[claim.id]||{};const targetVerified=!!(meta.date&&meta.verified&&$('claimInputVerified')?.checked)&&(!S.filename||!!S.pdf)&&!S.unread.length&&!claim.dependencyIssue;const candidate=targetVerified?slotResults.find(r=>r.dateKnown&&r.sourceChecked&&r.sameCombination&&S.prior[r.slot].date<meta.date):null;return {claimId:claim.id,group:group.length,slotResults,candidate,targetVerified};}
function assessmentHtml(){const counts=cellSummary(),unread=S.unread.length,errors=S.queryLog.filter(r=>r.status==='ERROR').length;let rows='';if(S.keywordOnly){rows='<p><strong>Keyword-only:</strong> Chỉ khảo sát chủ đề và đối chiếu concept; không có claims để nhận định tính mới hoặc trình độ sáng tạo. Khi có bộ yêu cầu bảo hộ, cần tạo hồ sơ claim-based riêng.</p>';}else{const items=S.claims.map(c=>assessClaim(c));rows='<p><strong>Nhận định theo từng claim:</strong> Các câu trích do AI đề xuất không tự trở thành kết luận.</p>'+items.map(r=>`<p><strong>Claim ${r.claimId}:</strong> ${r.candidate?`Có ứng viên tài liệu đơn lẻ ${esc(r.candidate.slot)} (${esc(r.candidate.no)}) đã được chuyên gia ghi nhận phủ mọi đặc điểm trong cùng tổ hợp; cần chuyên gia thẩm định tư cách đối chứng, các giới hạn và hệ quả pháp lý.`:'Chưa đủ cơ sở để khẳng định có tài liệu đơn lẻ bộc lộ toàn bộ claim. Kiểm tra mốc ngày, bản claims và chứng cứ; không đồng nghĩa claim đã có tính mới.'}</p>`).join('')+'<p><strong>Trình độ sáng tạo:</strong> Chờ chuyên gia đánh giá các khác biệt, tác dụng kỹ thuật, tư cách tài liệu và lập luận kết hợp; không suy diễn tự động từ D1 + D2 + D3.</p>';}
 return `${rows}<p class="muted small">${counts.checked}/${counts.total} ô có quyết định chuyên gia; ${counts.proposed} ô có gợi ý AI (không tính như xác nhận). ${unread} trang PDF còn chưa đọc đủ; ${errors} lượt tìm lỗi; ${Object.values(S.aiCoverage).filter(x=>!x.complete).length} tài liệu có lượt AI chưa hoàn tất. Độ phủ của nguồn tra cứu trên thế giới chưa được chứng minh.</p>${unread?'<p class="notice">Có trang PDF chưa đọc được. Không sử dụng trường hợp này để khẳng định đã khảo sát đủ input.</p>':''}`;}
function renderCombinationChecks(){if(S.keywordOnly)return '';return S.claims.map(c=>`<details><summary>Claim ${c.id} · kiểm tra quan hệ trong cùng một tài liệu (tùy khi có bằng chứng)</summary>${['D1','D2','D3'].map(slot=>{const d=S.prior[slot];if(!d?.no)return '';return `<label class="check"><input type="checkbox" data-combine="${esc(slot)}" data-claim="${c.id}" ${d.combinationClaims?.[c.id]?'checked':''}> Tôi đã đối chiếu bản gốc: ${slot} bộc lộ các giới hạn Claim ${c.id} trong <strong>cùng tổ hợp</strong>, không ghép từ tài liệu khác.</label>`}).join('')}</details>`).join('');}
function renderReport(){if(!S.features.length)S.features=featuresFromClaims();const datePanel=$('claimDatesReview');if(datePanel)datePanel.innerHTML=S.keywordOnly?'<p>Keyword-only: chưa có claim để xác định ngày liên quan.</p>':S.claims.map(c=>{const d=S.claimDates[c.id]||{};return `<div class="claim-preview"><label>Claim ${c.id} · mốc ngày liên quan (chuyên gia xác định)<input type="date" data-date-claim="${c.id}" value="${esc(d.date||'')}"></label><label class="check"><input type="checkbox" data-verify-date="${c.id}" ${d.verified?'checked':''}> Tôi đã xác định và kiểm tra tư cách ngày áp dụng đối với Claim ${c.id}.</label></div>`}).join('');datePanel?.querySelectorAll('[data-date-claim]').forEach(x=>x.onchange=()=>{const id=+x.dataset.dateClaim;S.claimDates[id]={date:x.value,verified:false};S.reportHtml='';renderReport();});datePanel?.querySelectorAll('[data-verify-date]').forEach(x=>x.onchange=()=>{const id=+x.dataset.verifyDate;S.claimDates[id]={date:S.claimDates[id]?.date||'',verified:x.checked};S.reportHtml='';renderReport();});$('conclusion').innerHTML=assessmentHtml()+'<details><summary>Chuyên gia kiểm tra điều kiện “cùng tổ hợp” theo claim</summary>'+renderCombinationChecks()+'</details>';$('conclusion').querySelectorAll('[data-combine]').forEach(input=>input.onchange=()=>{const slot=input.dataset.combine,d=S.prior[slot];if(d){if(!d.combinationClaims)d.combinationClaims={};d.combinationClaims[input.dataset.claim]=input.checked;}S.reportHtml='';renderReport();});$('expertNote').value=S.expertNote;$('expertSignoff').checked=S.signed;$('reportPreview').innerHTML=S.reportHtml;}
function reportCreate(){S.expertNote=$('expertNote').value.trim();S.signed=$('expertSignoff').checked;const results=S.keywordOnly?[]:S.claims.map(c=>assessClaim(c));const sourceRows=['D1','D2','D3'].filter(slot=>S.prior[slot]?.no).map(slot=>{const d=S.prior[slot];return `<tr><th>${slot}</th><td>${esc(d.no)}</td><td>${esc(d.date||'Chưa rõ')}</td><td>${esc(d.content_level||'Chưa xác định')}</td><td>${d.url?`<a href="${esc(safeUrl(d.url))}">${esc(safeUrl(d.url))}</a>`:'—'}</td></tr>`}).join('');const matrixRows=S.features.flatMap(f=>['D1','D2','D3'].map(slot=>{const r=S.matrix[matrixKey(f.id,slot)]||{},a=S.ai[matrixKey(f.id,slot)]||{};return `<tr><td>${esc(f.id)}</td><td>${esc(f.text)}</td><td>${slot}</td><td>${esc(a.status||'—')}</td><td>${esc(r.checked?r.status:'Chưa có xác nhận')}</td><td>${esc(r.quote||'')}</td><td>${esc(r.location||'')}</td><td>${esc(r.note||'')}</td></tr>`})).join('');const resultHtml=results.length?results.map(r=>`<p>Claim ${r.claimId}: ${r.candidate?`Có ứng viên ${esc(r.candidate.slot)} được ghi nhận phủ đủ đặc điểm trong cùng tổ hợp, ngày công bố trước mốc đã xác minh; chưa phải quyết định pháp lý.`:'Chưa đủ cơ sở khẳng định thiếu tính mới; còn thiếu mốc ngày/bản claims hoặc bằng chứng; cũng không chứng minh có tính mới.'}</p>`).join(''):'<p>Không có claims: chỉ báo cáo chủ đề và mức liên quan của các concept; không đánh giá tính mới/trình độ sáng tạo.</p>';S.reportHtml=`<h2>PatentLens AI · Báo cáo nghiên cứu ${S.signed?'(đã ghi nhận rà soát chuyên gia)':'(DỰ THẢO — CHƯA DUYỆT)'}</h2><p>Ngày tạo: ${esc(new Date().toLocaleString('vi-VN'))} · Đầu vào: ${esc(S.filename||'văn bản người dùng cung cấp')} · Bối cảnh: ${S.mode==='prospective'?'Chuẩn bị đăng ký':'Kiểm thử hồ sơ công khai'}</p><p>Định tuyến: ${esc(S.route?.topics.map(t=>t.name).join(' · ')||'Chưa xác định')}; hình thức đầu vào: ${S.keywordOnly?'keyword-only':'claims ('+S.claims.length+')'}.</p><p>Kiểm toán: đã rà thuật ngữ ${S.routeAudit?.scannedChars||0}/${S.routeAudit?.totalChars||0} ký tự đã nạp; PDF còn ${S.unread.length} trang chưa đọc đủ. Đã có ${(S.queryLog||[]).length} lượt log, ${(S.queryLog||[]).filter(r=>r.status==='ERROR').length} lượt lỗi.</p><h3>Nhận định sơ bộ</h3>${resultHtml}<p>Trình độ sáng tạo: chờ chuyên gia phân tích riêng; các dữ liệu trong báo cáo chưa phải ý kiến pháp lý cuối cùng.</p><h3>Tài liệu được chọn</h3><table><thead><tr><th>Ô</th><th>Mã công bố</th><th>Ngày công bố</th><th>Mức nội dung đã nạp</th><th>URL gốc</th></tr></thead><tbody>${sourceRows}</tbody></table><h3>Ma trận · máy đề xuất / chuyên gia xác nhận</h3><table><thead><tr><th>ID</th><th>Feature/concept</th><th>Nguồn</th><th>AI gợi ý</th><th>Đã xác nhận</th><th>Đoạn nguồn</th><th>Vị trí</th><th>Lý do</th></tr></thead><tbody>${matrixRows}</tbody></table><h3>Nhận xét và phạm vi rà soát</h3><p>${esc(S.expertNote||'Chưa có nhận xét bổ sung.')}</p><p>${S.signed?'Đã ghi nhận người dùng tích xác nhận rà soát, không có cơ chế xác thực danh tính hay chữ ký số.':'Chưa được chuyên gia xác nhận.'}</p><p class="muted">Báo cáo không chứng minh tra cứu bao phủ toàn thế giới, đọc đủ hình vẽ, hiệu lực ưu tiên hoặc đánh giá pháp lý. Mỗi câu trích phải kiểm tra với tài liệu gốc. Không cộng nhiều tài liệu khác nhau để kết luận một claim thiếu tính mới.</p>`;$('reportPreview').innerHTML=S.reportHtml;notify('Đã tạo báo cáo '+(S.signed?'có ghi nhận rà soát.':'dự thảo, chưa duyệt.'));}
function fileDownload(name,content,type){const blob=new Blob([content],{type}),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),1000);}
function exportHtml(){if(!S.reportHtml)reportCreate();fileDownload('PatentLens_report.html','<!doctype html><html lang="vi"><meta charset="utf-8"><title>PatentLens Research</title><style>body{font:13px/1.6 Arial;margin:32px;color:#222}table{border-collapse:collapse;width:100%}td,th{border:1px solid #aaa;padding:6px;vertical-align:top}h2{border-bottom:1px solid #555}@media print{body{margin:12mm}}</style>'+S.reportHtml,'text/html;charset=utf-8');}
function exportCsv(){const rows=[['ID','Feature/concept','Claim','Nguồn','AI gợi ý','Chuyên gia xác nhận','Trích dẫn','Vị trí','Nhận xét']];for(const f of S.features)for(const slot of ['D1','D2','D3']){const r=S.matrix[matrixKey(f.id,slot)]||{},a=S.ai[matrixKey(f.id,slot)]||{};rows.push([f.id,f.text,f.claimId||'',slot,a.status||'',r.checked?r.status:'CHƯA DUYỆT',r.quote||'',r.location||'',r.note||'']);}const csv='\ufeff'+rows.map(cols=>cols.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');fileDownload('PatentLens_matrix.csv',csv,'text/csv;charset=utf-8');}
function saveDraft(){const data={schema:'patentlens-v38',mode:S.mode,source:S.source,filename:S.filename,fileMeta:S.fileMeta,pagesAudit:S.pages.map(p=>({page:p.page,length:p.text.length,status:p.status})),unread:S.unread,claims:S.claims,keywordOnly:S.keywordOnly,route:S.route,concepts:S.concepts,queries:S.queries,queryLog:S.queryLog,candidates:S.candidates,prior:S.prior,features:S.features,matrix:S.matrix,ai:S.ai,aiCoverage:S.aiCoverage,expertNote:S.expertNote,signed:S.signed,when:new Date().toISOString()};fileDownload('PatentLens_nhap_v38.json',JSON.stringify(data,null,2),'application/json;charset=utf-8');notify('Đã lưu JSON nháp vào máy, KHÔNG gồm PDF gốc và chưa mã hóa. Không gửi nháp chứa hồ sơ mật.');}
async function openDraft(file){if(!file)return;try{const data=JSON.parse(await file.text());if(data.schema!=='patentlens-v38')throw Error('Chỉ hỗ trợ nháp v38; không tự tin vào dữ liệu quyết định cũ từ phiên bản khác.');S.mode=data.mode||'prospective';S.source=String(data.source||'');S.filename=data.filename||'';S.fileMeta=data.fileMeta||null;S.pages=[];S.unread=[...(data.unread||[])];S.pdf=null;S.claims=parseStructuredClaims(S.source);S.keywordOnly=!S.claims.length;S.claimDates={};S.route=null;S.concepts=[];S.queries=data.queries||[];S.queryLog=data.queryLog||[];S.candidates=data.candidates||[];S.prior=data.prior||{D1:null,D2:null,D3:null};for(const d of Object.values(S.prior))if(d){d.sourceChecked=false;d.dateChecked=false;d.docIdentityChecked=false;d.combinationClaims={};}S.features=[];S.matrix={};S.ai={};S.aiCoverage={};S.expertNote=data.expertNote||'';S.signed=false;S.reportHtml='';$('sourceText').value=S.source;$('fileName').textContent=S.filename?'Nháp tham chiếu PDF: '+S.filename+' (cần nạp lại để kiểm tra)':'Đã mở văn bản trong nháp';$('ingestState').textContent='Đã mở nháp; mọi bằng chứng và ngày từ JSON phải được kiểm tra lại. Các xác nhận cũ đã xóa khỏi ma trận.';document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.mode===S.mode));if(S.filename)S.unread=S.unread.length?S.unread:['Cần nạp lại PDF gốc'];stepShow(0);notify('Đã mở nháp. Tải lại PDF bản gốc và xác nhận nguồn trước khi dùng kết quả nghiên cứu.');}catch(e){notify('Không mở được nháp: '+String(e.message||e),true);}}
/* PDF input: read every available text layer with page-level exceptions and yield to UI.
   OCR scanned/weak pages explicitly, never declare them complete prematurely. */
const PDFJS_URL='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';
let pdfLibPromise=null;
function loadScript(url){return new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=url;s.onload=resolve;s.onerror=()=>reject(Error('Không tải được thư viện từ '+url));document.head.appendChild(s);});}
async function pdfLibrary(){if(!pdfLibPromise)pdfLibPromise=(async()=>{if(!window.pdfjsLib)await loadScript(PDFJS_URL);if(!window.pdfjsLib)throw Error('Không có PDF.js');pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';return window.pdfjsLib;})();return pdfLibPromise;}
function readPageText(content){let text='';for(const it of content.items||[]){const piece=String(it.str||'');if(!piece)continue;text+=piece;if(it.hasEOL)text+='\n';else if(!/\s$/.test(piece))text+=' ';}return text.replace(/[ \t]+\n/g,'\n').normalize('NFC');}
function refreshInputPageState(){S.unread=S.pages.filter(p=>p.status!=='text'&&p.status!=='ocr').map(p=>p.page);const total=S.pdf?.numPages||S.pages.length,done=S.pages.filter(p=>p.status==='text'||p.status==='ocr').length;$('pageAudit').textContent=S.pdf?`${done}/${total} trang có nội dung chữ · ${S.unread.length} trang chưa đọc đủ / bị lỗi. Phần hình vẽ, công thức và bảng vẫn cần đối chiếu bản PDF gốc.`:'';$('ocrMissing').hidden=!S.pdf||!S.unread.length||S.pdfBusy;$('ocrAll').hidden=!S.pdf||S.unread.length<=8||S.pdfBusy;$('stopPdf').hidden=!S.pdfBusy;}
async function readPdfFile(file){if(!file)return;if(!/\.pdf$/i.test(file.name)&&file.type!=='application/pdf')return notify('Hiện tại trang này chỉ hỗ trợ PDF hoặc dán văn bản. Không tự coi DOCX/ảnh là đã đọc.',true);S.pdfAbort=false;S.pdfBusy=true;S.pdf=null;S.pages=[];S.unread=[];S.uploadId++;S.ocrToken++;invalidate(1);S.source='';S.claims=[];S.keywordOnly=true;$('claimsPreview').innerHTML='';$('searchQueries').value='';S.fileMeta={name:file.name,size:file.size};S.filename=file.name;$('fileName').textContent=`${file.name} · ${(file.size/1024/1024).toFixed(1)} MB`;$('sourceText').value='';$('ingestState').textContent='Đang mở PDF và đọc lớp chữ theo trang...';$('ingestProgress').style.width='1%';refreshInputPageState();const generation=S.revision,uploadId=S.uploadId;
 try{const lib=await pdfLibrary();const buffer=await file.arrayBuffer();if(S.pdfAbort)return;const pdf=await lib.getDocument({data:new Uint8Array(buffer)}).promise;S.pdf=pdf;S.pages=Array.from({length:pdf.numPages},(_,i)=>({page:i+1,text:'',status:'pending'}));refreshInputPageState();for(let i=0;i<pdf.numPages;i++){
  if(S.pdfAbort||generation!==S.revision||uploadId!==S.uploadId)break;const record=S.pages[i];try{const page=await Promise.race([pdf.getPage(i+1),new Promise((_,reject)=>setTimeout(()=>reject(Error('Trang tải quá 25 giây')),25000))]);const content=await Promise.race([page.getTextContent(),new Promise((_,reject)=>setTimeout(()=>reject(Error('Lớp chữ trang quá 25 giây')),25000))]);const text=readPageText(content);record.text=text;record.status=text.replace(/\s/g,'').length>=45?'text':'weak';page.cleanup();}catch(e){record.status='error';record.error=String(e.message||e);}
  const finished=i+1;$('ingestProgress').style.width=Math.round(finished/pdf.numPages*100)+'%';$('ingestState').textContent=`Đọc lớp chữ PDF: trang ${finished}/${pdf.numPages} · ${S.pages.filter(p=>p.status==='text').length} trang có chữ, chưa OCR trang scan.`;if(finished%3===0||finished===pdf.numPages){refreshInputPageState();await new Promise(requestAnimationFrame);}
 }
 if(S.pdfAbort||uploadId!==S.uploadId||generation!==S.revision){if(uploadId===S.uploadId)$('ingestState').textContent='Đã dừng đọc PDF; cần mở lại để kiểm tra các trang còn thiếu.';return;}const text=S.pages.map(p=>p.text?'[TRANG '+p.page+']\n'+p.text:'').filter(Boolean).join('\n\n');if(text.trim())setInput(text,file.name);else notify('Không trích được chữ từ PDF. Hãy dùng OCR bổ sung ở các trang cần đọc.',true);$('ingestState').textContent=S.pdfAbort?`Đã dừng ở ${S.pages.filter(p=>p.status!=='pending').length}/${pdf.numPages} trang. Chưa đọc đủ; mở lại PDF hoặc OCR phần còn thiếu.`:`Đã kiểm tra lớp chữ ${pdf.numPages} trang · ${S.unread.length} trang cần OCR/kiểm tra. ${S.claims.length?'Nhận diện '+S.claims.length+' claims.':'Chưa thấy claims có cấu trúc; có thể dùng keyword-only.'}`;
 }catch(e){notify('Không mở/đọc được PDF: '+String(e.message||e)+'. Có thể thử dán văn bản hoặc gửi file PDF gốc để kiểm tra.',true);$('ingestState').textContent='Đọc PDF thất bại; không đánh dấu đã hoàn tất.';}finally{if(uploadId===S.uploadId){S.pdfBusy=false;refreshInputPageState();}}}
let ocrLibPromise=null;
async function tesseractLibrary(){if(!ocrLibPromise)ocrLibPromise=(async()=>{if(!window.Tesseract)await loadScript('https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js');if(!window.Tesseract)throw Error('Không tải được OCR engine');return window.Tesseract;})();return ocrLibPromise;}
async function ocrMissingPages(all=false){if(!S.pdf||S.pdfBusy)return;const sourcePdf=S.pdf,uploadId=S.uploadId,token=++S.ocrToken;S.pdfAbort=false;S.pdfBusy=true;refreshInputPageState();let worker=null;try{const t=await tesseractLibrary();worker=await t.createWorker('vie+eng',1,{});const candidates=S.pages.filter(p=>p.status!=='text'&&p.status!=='ocr');const work=all?candidates:candidates.slice(0,8);if(!work.length)return;for(let i=0;i<work.length;i++){if(S.pdfAbort||S.pdf!==sourcePdf||S.uploadId!==uploadId||S.ocrToken!==token)break;const item=work[i];$('ingestState').textContent=`OCR bổ sung trang ${item.page}/${S.pdf.numPages} (${i+1}/${work.length} trang trong đợt)...`;try{const page=await S.pdf.getPage(item.page),vp=page.getViewport({scale:1.6}),canvas=document.createElement('canvas');canvas.width=Math.floor(vp.width);canvas.height=Math.floor(vp.height);await page.render({canvasContext:canvas.getContext('2d'),viewport:vp}).promise;const response=await worker.recognize(canvas);const text=String(response.data?.text||'').normalize('NFC');if(text.replace(/\s/g,'').length>=35){item.text=text;item.status='ocr';}else{item.status='weak';item.error='OCR trả quá ít chữ';}canvas.width=canvas.height=0;page.cleanup();}catch(e){item.status='error';item.error=String(e.message||e);}refreshInputPageState();await new Promise(requestAnimationFrame);}if(S.pdfAbort||S.pdf!==sourcePdf||S.uploadId!==uploadId||S.ocrToken!==token)return;const merged=S.pages.filter(p=>p.text).map(p=>'[TRANG '+p.page+']\n'+p.text).join('\n\n');if(merged.trim())setInput(merged,S.filename);$('ingestState').textContent=`Đã thử OCR bổ sung. Còn ${S.unread.length} trang chưa đọc đủ${S.unread.length?'; bấm OCR bổ sung để xử lý đợt tiếp hoặc kiểm tra bản gốc.':'. Hình vẽ vẫn cần đọc bản gốc.'}`;}catch(e){notify('OCR không thực hiện được: '+String(e.message||e)+'. Vẫn giữ trang chưa đọc, không đánh dấu hoàn tất.',true);}finally{try{await worker?.terminate();}catch{}if(S.pdf===sourcePdf&&S.uploadId===uploadId){S.pdfBusy=false;refreshInputPageState();}}}
function validateNext(){if(S.stage===0)return inputDataRequired();if(S.stage===1){if(!S.route)renderRoute();return !!S.source.trim();}if(S.stage===2){if(!['D1','D2','D3'].some(slot=>S.prior[slot]?.no)){notify('Chưa có D1–D3 để so sánh. Hãy tìm hoặc nhập ít nhất một tài liệu công khai.',true);return false;}return true;}return true;}
function bind(){stepShow(0);document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{S.mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('selected',x===b));});$('claimInputVerified').onchange=()=>{S.reportHtml='';renderReport();};$('useText').onclick=()=>{S.pdfAbort=true;S.uploadId++;S.ocrToken++;S.pdf=null;S.pages=[];S.unread=[];S.pdfBusy=false;S.fileMeta=null;setInput($('sourceText').value);$('pageAudit').textContent='Đầu vào là văn bản dán, không có PDF gốc để xác minh.';};$('pdfFile').onchange=e=>readPdfFile(e.target.files?.[0]);$('stopPdf').onclick=()=>{S.pdfAbort=true;$('ingestState').textContent='Đang dừng sau trang hiện tại...';};$('ocrMissing').onclick=()=>ocrMissingPages(false);$('ocrAll').onclick=()=>{if(confirm('OCR toàn bộ '+S.unread.length+' trang còn thiếu có thể rất chậm hoặc hết bộ nhớ. Bạn có thể bấm Dừng; các trang lỗi sẽ được ghi nhận. Tiếp tục?'))ocrMissingPages(true);};$('back').onclick=()=>stepShow(S.stage-1);$('next').onclick=()=>{if(S.stage===4){reportCreate();return;}if(!validateNext())return;stepShow(S.stage+1);};$('searchQueries').addEventListener('input',renderSourceLinks);$('runSearch').onclick=runSearch;$('stopSearch').onclick=()=>S.searchAbort?.abort();$('autoPick').onclick=()=>{for(let i=0;i<3;i++)if(S.candidates[i])selectPrior(['D1','D2','D3'][i],S.candidates[i]);notify('Đã chọn ba ứng viên theo ưu tiên từ metadata/snippet. Chưa xác minh tính liên quan kỹ thuật hoặc ngày.');};$('buildChart').onclick=()=>{S.features=featuresFromClaims();S.matrix={};S.ai={};renderMatrix();notify('Đã tạo ma trận mới; các xác nhận cũ đã được xóa để tránh dùng sai feature.');};$('aiAssist').onclick=runAi;$('makeReport').onclick=reportCreate;$('exportHtml').onclick=exportHtml;$('exportCsv').onclick=exportCsv;$('saveDraft').onclick=saveDraft;$('openDraft').onchange=e=>openDraft(e.target.files?.[0]);}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bind);else bind();
